/*
 | Приём заявок.
 |
 | Форма отправляется обычным POST и заканчивается переходом на
 | страницу благодарности: так заявка уходит даже при отключённом
 | JavaScript. Отдельного JSON-адреса намеренно нет.
 */

interface ILeadApiPost {
    /**
     * Заявка со всех форм сайта.
     */
    '/lead': (lead: ILead) => void;
}
